const body = $input.first().json.body;

const supplier = body.supplier;
const items = body.items;
const alamat_kirim = body.alamat_kirim;
const terms = body.terms || 'Net 30';

// Generate nomor PO: PO/YYYYMMDD/XXX
const now = new Date();
const yyyy = now.getFullYear();
const mm = String(now.getMonth() + 1).padStart(2, '0');
const dd = String(now.getDate()).padStart(2, '0');
const seq = String(Math.floor(Math.random() * 999) + 1).padStart(3, '0');
const nomor_po = `PO/${yyyy}${mm}${dd}/${seq}`;

// Format Rupiah
function formatRupiah(amount) {
  return 'Rp ' + amount.toLocaleString('id-ID');
}

// Calculate subtotal
let subtotal = 0;
const itemDetails = items.map((item, idx) => {
  const lineTotal = item.qty * item.harga_satuan;
  subtotal += lineTotal;
  return {
    no: idx + 1,
    kode_barang: item.kode_barang,
    nama: item.nama,
    qty: item.qty,
    satuan: item.satuan,
    harga_satuan: item.harga_satuan,
    harga_satuan_formatted: formatRupiah(item.harga_satuan),
    line_total: lineTotal,
    line_total_formatted: formatRupiah(lineTotal)
  };
});

// PPN 11%
const ppn = Math.round(subtotal * 0.11);
const total = subtotal + ppn;

// Build item table for email
const itemTableRows = itemDetails.map(i =>
  `<tr><td>${i.no}</td><td>${i.kode_barang}</td><td>${i.nama}</td><td>${i.qty} ${i.satuan}</td><td>${i.harga_satuan_formatted}</td><td>${i.line_total_formatted}</td></tr>`
).join('\n');

const emailBody = `
<h2>PURCHASE ORDER</h2>
<p><strong>Nomor PO:</strong> ${nomor_po}</p>
<p><strong>Tanggal:</strong> ${dd}/${mm}/${yyyy}</p>
<p><strong>Supplier:</strong> ${supplier.nama}</p>
<p><strong>Kontak:</strong> ${supplier.kontak || '-'}</p>
<p><strong>Email Supplier:</strong> ${supplier.email}</p>
<hr/>
<h3>Detail Pesanan</h3>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%">
<thead><tr style="background:#f0f0f0"><th>No</th><th>Kode Barang</th><th>Nama Barang</th><th>Qty</th><th>Harga Satuan</th><th>Jumlah</th></tr></thead>
<tbody>
${itemTableRows}
</tbody>
</table>
<br/>
<table cellpadding="4">
<tr><td><strong>Subtotal</strong></td><td>${formatRupiah(subtotal)}</td></tr>
<tr><td><strong>PPN 11%</strong></td><td>${formatRupiah(ppn)}</td></tr>
<tr><td><strong>Total</strong></td><td><strong>${formatRupiah(total)}</strong></td></tr>
</table>
<hr/>
<p><strong>Alamat Kirim:</strong><br/>${alamat_kirim}</p>
<p><strong>Terms Pembayaran:</strong> ${terms}</p>
<br/>
<p>Mohon konfirmasi penerimaan PO ini dan estimasi waktu pengiriman.</p>
<p>Terima kasih atas kerjasamanya.</p>
`;

const telegramMsg = `📋 *PO Baru Dibuat*\n\n` +
  `*Nomor:* ${nomor_po}\n` +
  `*Supplier:* ${supplier.nama}\n` +
  `*Items:* ${items.length} jenis barang\n` +
  `*Subtotal:* ${formatRupiah(subtotal)}\n` +
  `*PPN 11%:* ${formatRupiah(ppn)}\n` +
  `*Total:* ${formatRupiah(total)}\n` +
  `*Terms:* ${terms}\n` +
  `*Alamat Kirim:* ${alamat_kirim}`;

return {
  nomor_po,
  tanggal: `${dd}/${mm}/${yyyy}`,
  supplier,
  items: itemDetails,
  alamat_kirim,
  terms,
  subtotal,
  subtotal_formatted: formatRupiah(subtotal),
  ppn,
  ppn_formatted: formatRupiah(ppn),
  total,
  total_formatted: formatRupiah(total),
  email_body: emailBody,
  telegram_message: telegramMsg,
  supplier_email: supplier.email,
  email_subject: `Purchase Order ${nomor_po} - Mohon Konfirmasi`
};

